/**
 * Count of bytes &ge; 0x80 in the probe.
 */
public static int countHighBytes(byte[] probe) {
    if (probe == null) {
        return 0;
    }
    int n = 0;
    for (byte b : probe) {
        if ((b & 0xFF) >= 0x80) {
            n++;
        }
    }
    return n;
}
